UPDATE MGCMTBLDEF SET KEY_1_SIZE = 30 WHERE TABLE_NAME = 'QCM_VENDOR';
UPDATE MGCMTBLDEF SET KEY_1_SIZE = 20 WHERE TABLE_NAME = 'SHEET_DATA_TYPE';
UPDATE MGCMTBLDEF SET KEY_1_SIZE = 20 WHERE TABLE_NAME = 'SHEET_QUERY_TYPE';
UPDATE MGCMTBLDEF SET KEY_1_SIZE = 20 WHERE TABLE_NAME = 'SHEET_SHEET_TYPE';
